import subprocess, sys, os, json, time, glob, shutil
T0 = time.time()
CHUNK = 0
MY_ROLES = ["aberration", "absurdist", "accountant", "activist", "actor", "addict", "adolescent", "advocate", "alien", "altruist", "amateur", "ambassador", "amnesiac", "analyst", "anarchist", "ancient", "angel", "anthropologist", "archaeologist", "architect", "archivist", "artisan", "ascetic", "assistant"]
QCOUNT = 24
DEADLINE = 11.25 * 3600          # Kaggle kills sessions at 12 h and then saves nothing
GEN_SUBBATCH = 4
EST = {'gen_role': 1100.0, 'gen_load': 300.0, 'judge_role': 170.0, 'act_role': 100.0, 'fixed': 1200.0}
el = lambda: time.time() - T0
log = lambda *a: print(f'[{el()/3600:5.2f}h]', *a, flush=True)

